package wasm

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
	"time"
)

// LocalResponse is a response generated by the plugin (proxy_send_local_response).
type LocalResponse struct {
	Status     int
	Header     http.Header
	Body       []byte
	GRPCStatus int32
}

// Properties resolves proxy_get_property paths for a stream.
type Properties func(path []string) ([]byte, bool)

// Stream is one HTTP context: a request/response pair running through the
// plugin. Host functions read and mutate the fields below while a callback
// runs; the owning instance's lock serializes access.
type Stream struct {
	inst  *instance
	id    uint32
	props Properties

	Req      *http.Request
	ReqBody  []byte
	Resp     *http.Response
	RespBody []byte

	local   *LocalResponse
	resumed bool
	pending *callout

	callResp *http.Response
	callBody []byte
	done     bool
}

type callout struct {
	token   uint32
	cluster string
	req     *http.Request
	timeout time.Duration
}

// NewStream creates an HTTP context on one of the plugin's instances.
func (p *Plugin) NewStream(ctx context.Context, props Properties) (*Stream, error) {
	inst, err := p.pick(ctx)
	if err != nil {
		return nil, err
	}
	inst.mu.Lock()
	id := inst.nextID
	inst.nextID++
	inst.mu.Unlock()
	s := &Stream{inst: inst, id: id, props: props}
	if _, err := inst.call(ctx, s, "proxy_on_context_create", uint64(id), rootContextID); err != nil {
		return nil, err
	}
	return s, nil
}

// Local returns the plugin's local response, if it produced one.
func (s *Stream) Local() *LocalResponse { return s.local }

func b2u(b bool) uint64 {
	if b {
		return 1
	}
	return 0
}

// run executes a phase callback and then services HTTP callouts until the
// plugin resumes, answers locally, or stops asking for more.
func (s *Stream) run(ctx context.Context, fn string, args ...uint64) error {
	if s.local != nil {
		return nil
	}
	if _, err := s.inst.call(ctx, s, fn, args...); err != nil {
		return err
	}
	for s.pending != nil && s.local == nil {
		c := s.pending
		s.pending, s.resumed = nil, false
		s.callResp, s.callBody = nil, nil
		resp, body, err := s.doCallout(ctx, c)
		numHeaders, bodySize := uint64(0), uint64(0)
		if err == nil {
			s.callResp, s.callBody = resp, body
			numHeaders, bodySize = uint64(len(headerPairs(resp.Header))+1), uint64(len(body))
		} else {
			s.inst.p.log.Warn("http callout failed", "cluster", c.cluster, "err", err)
		}
		// The SDK dispatches the callback to the calling stream itself.
		if _, err := s.inst.call(ctx, s, "proxy_on_http_call_response", rootContextID, uint64(c.token), numHeaders, bodySize, 0); err != nil {
			return err
		}
	}
	return nil
}

func (s *Stream) doCallout(ctx context.Context, c *callout) (*http.Response, []byte, error) {
	if s.inst.p.callouts == nil {
		return nil, nil, errors.New("http callouts are not available")
	}
	ctx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()
	resp, err := s.inst.p.callouts.HTTPCall(ctx, c.cluster, c.req.WithContext(ctx))
	if err != nil {
		return nil, nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	return resp, body, err
}

func (s *Stream) OnRequestHeaders(ctx context.Context, endOfStream bool) error {
	return s.run(ctx, "proxy_on_request_headers", uint64(s.id), uint64(len(s.requestPairs())), b2u(endOfStream))
}

func (s *Stream) OnRequestBody(ctx context.Context) error {
	return s.run(ctx, "proxy_on_request_body", uint64(s.id), uint64(len(s.ReqBody)), 1)
}

func (s *Stream) OnResponseHeaders(ctx context.Context, endOfStream bool) error {
	return s.run(ctx, "proxy_on_response_headers", uint64(s.id), uint64(len(s.responsePairs())), b2u(endOfStream))
}

func (s *Stream) OnResponseBody(ctx context.Context) error {
	return s.run(ctx, "proxy_on_response_body", uint64(s.id), uint64(len(s.RespBody)), 1)
}

// Done finishes the context (on_done, on_log, on_delete). Safe to call once
// the request is complete, whether or not every phase ran.
func (s *Stream) Done(ctx context.Context) {
	if s.done || s.inst.broken.Load() {
		return
	}
	s.done = true
	_, _ = s.inst.call(ctx, s, "proxy_on_done", uint64(s.id))
	_, _ = s.inst.call(ctx, s, "proxy_on_log", uint64(s.id))
	_, _ = s.inst.call(ctx, s, "proxy_on_delete", uint64(s.id))
}

// --- header maps, with HTTP/2-style pseudo-headers and lowercase names ---

func headerPairs(h http.Header) [][2]string {
	keys := make([]string, 0, len(h))
	for k := range h {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var out [][2]string
	for _, k := range keys {
		lk := strings.ToLower(k)
		for _, v := range h[k] {
			out = append(out, [2]string{lk, v})
		}
	}
	return out
}

func (s *Stream) requestPairs() [][2]string {
	r := s.Req
	if r == nil {
		return nil
	}
	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	pairs := [][2]string{{":method", r.Method}, {":path", r.URL.RequestURI()}, {":authority", r.Host}, {":scheme", scheme}}
	return append(pairs, headerPairs(r.Header)...)
}

func (s *Stream) responsePairs() [][2]string {
	if s.Resp == nil {
		return nil
	}
	return append([][2]string{{":status", strconv.Itoa(s.Resp.StatusCode)}}, headerPairs(s.Resp.Header)...)
}

func (s *Stream) pairs(mapType uint32) ([][2]string, bool) {
	switch mapType {
	case mapRequestHeaders:
		return s.requestPairs(), s.Req != nil
	case mapResponseHeaders:
		return s.responsePairs(), s.Resp != nil
	case mapCallResponseHeaders:
		if s.callResp == nil {
			return nil, false
		}
		return append([][2]string{{":status", strconv.Itoa(s.callResp.StatusCode)}}, headerPairs(s.callResp.Header)...), true
	case mapRequestTrailers, mapResponseTrailers, mapCallResponseTrailer:
		return nil, true
	}
	return nil, false
}

// setHeader applies one mutation. op is add, replace or remove.
func (s *Stream) setHeader(mapType uint32, op, key, value string) status {
	key = strings.ToLower(key)
	switch mapType {
	case mapRequestHeaders:
		if s.Req == nil {
			return statusNotFound
		}
		if strings.HasPrefix(key, ":") {
			return s.setRequestPseudo(op, key, value)
		}
		return mutate(s.Req.Header, op, key, value)
	case mapResponseHeaders:
		if s.Resp == nil {
			return statusNotFound
		}
		if key == ":status" {
			code, err := strconv.Atoi(value)
			if err != nil || op == "remove" {
				return statusBadArgument
			}
			s.Resp.StatusCode, s.Resp.Status = code, fmt.Sprintf("%d %s", code, http.StatusText(code))
			return statusOK
		}
		return mutate(s.Resp.Header, op, key, value)
	case mapRequestTrailers, mapResponseTrailers:
		return statusOK // trailers are not exposed to plugins; mutations are no-ops
	}
	return statusBadArgument
}

func mutate(h http.Header, op, key, value string) status {
	switch op {
	case "add":
		h.Add(key, value)
	case "replace":
		h.Set(key, value)
	case "remove":
		h.Del(key)
	}
	return statusOK
}

func (s *Stream) setRequestPseudo(op, key, value string) status {
	if op == "remove" {
		return statusBadArgument
	}
	r := s.Req
	switch key {
	case ":path":
		u, err := url.ParseRequestURI(value)
		if err != nil {
			return statusBadArgument
		}
		r.URL.Path, r.URL.RawPath, r.URL.RawQuery = u.Path, u.RawPath, u.RawQuery
	case ":method":
		r.Method = value
	case ":authority":
		r.Host = value
	case ":scheme":
	default:
		return statusBadArgument
	}
	return statusOK
}

// replaceAll implements proxy_set_header_map_pairs.
func (s *Stream) replaceAll(mapType uint32, pairs [][2]string) status {
	var h http.Header
	switch mapType {
	case mapRequestHeaders:
		if s.Req == nil {
			return statusNotFound
		}
		h = s.Req.Header
	case mapResponseHeaders:
		if s.Resp == nil {
			return statusNotFound
		}
		h = s.Resp.Header
	default:
		return statusBadArgument
	}
	for k := range h {
		delete(h, k)
	}
	for _, p := range pairs {
		op := "add"
		if strings.HasPrefix(p[0], ":") {
			op = "replace" // pseudo-headers map onto single request/response fields
		}
		if st := s.setHeader(mapType, op, p[0], p[1]); st != statusOK {
			return st
		}
	}
	return statusOK
}

// --- buffers ---

func (s *Stream) buffer(t uint32) (*[]byte, bool) {
	switch t {
	case bufferRequestBody:
		return &s.ReqBody, s.Req != nil
	case bufferResponseBody:
		return &s.RespBody, s.Resp != nil
	case bufferCallResponseBody:
		return &s.callBody, s.callResp != nil
	}
	return nil, false
}

// setBuffer follows Envoy: start 0 drops `length` leading bytes and
// prepends data (length >= size replaces); start >= size appends.
func setBuffer(buf *[]byte, start, length uint32, data []byte) status {
	b := *buf
	switch {
	case start == 0:
		drop := min(int(length), len(b))
		*buf = append(append([]byte{}, data...), b[drop:]...)
	case int(start) >= len(b):
		*buf = append(b, data...)
	default:
		return statusBadArgument
	}
	return statusOK
}
